CREATE PROCEDURE dbo.Locko_GetPortletContent
    @status_list                    xml                 = NULL, -- список статусов XML вида <items><item id="1" /><item id="1" /><item id="3" /><item id="4" /></items>
    @app_executor_groups            xml                 = NULL, -- список Групп Исполнителей Заявок XML вида <items><item id="1" /><item id="1" /><item id="3" /><item id="4" /></items>
    @incoming_channel               xml                 = NULL, -- Канал поступления, список - XML вида <items><item id="1" /><item id="1" /><item id="3" /><item id="4" /></items>
    @region                         xml                 = NULL, -- Регион оформления кредита, список - XML вида <items><item id="1" /><item id="1" /><item id="3" /><item id="4" /></items>
    @branch                         xml                 = NULL, -- Отделение, список - XML вида <items><item id="1" /><item id="1" /><item id="3" /><item id="4" /></items>
    @executor                       xml                 = NULL, -- Исполнители, список - XML вида <items><item id="1" /><item id="1" /><item id="3" /><item id="4" /></items>
    @application_status             xml                 = NULL, -- Статус заявки, список - XML вида <items><item id="1" /><item id="1" /><item id="3" /><item id="4" /></items>
    @utm_labels                     xml                 = NULL, -- Cписок меток XML вида <items><item id="smarterpro" /><item id="yandex" /></items>
    @application_number             nvarchar(100)       = NULL, -- номер заявки
    @current_user                   bigint              = NULL, -- Текущий пользователь
    @full_name                      nvarchar(300)       = NULL, -- основной заёмщик ФИО
    @birth_date                     datetime            = NULL, -- основной заёмщик дата рождения
    @passport_series                nvarchar(50)        = NULL, -- основной заёмщик серия паспорта
    @passport_number                nvarchar(50)        = NULL, -- основной заёмщик номер паспорта
    @phone                          nvarchar(50)        = NULL, -- номер телефона основного заёмщика
    @creation_date_begin            datetime            = NULL, -- Дата создания ОТ
    @creation_date_end              datetime            = NULL, -- Дата создания ДО
    @approval_date_begin            datetime            = NULL, -- Дата одобрения ОТ
    @approval_date_end              datetime            = NULL, -- Дата одобрения ДО
    @date_of_completion_begin       datetime            = NULL, -- Дата заполнения ОТ
    @date_of_completion_end         datetime            = NULL, -- Дата заполнения ДО
    @creation_author                bigint              = NULL, -- Автор создания
    @manager_issued                 bigint              = NULL, -- Сотрудник, который выдал кредит
    @manager_fullfilled             bigint              = NULL, -- Сотрудник, который завершил заполнение заявки
    @manager_declined               bigint              = NULL, -- Сотрудник, который выбрал отказ или брак
    @amount_requested_begin         money               = NULL, -- Запрошенная сумма ОТ
    @amount_requested_end           money               = NULL, -- Запрошенная сумма ДО
    @loan_amount_preDecision_begin  money               = NULL, -- Сумма по предварительному решению ОТ
    @loan_amount_preDecision_end    money               = NULL, -- Сумма по предварительному решению ДО
    @loan_amount_begin              money               = NULL, -- Сумма из выбранного решения ОТ
    @loan_amount_end                money               = NULL, -- Сумма из выбранного решения ДО
    @role                           bit                 = 0,    -- 1 - КА; 0 или NULL  - остальные роли
    @additional_filtering           smallint            = NULL, -- одно из допустимых значений
                                                                -- По региону - 1
                                                                -- По отделению - 2
                                                                -- Дистанционный офис - 3
                                                                -- Колл-центр - 4
                                                                -- если будет передано неизвестное значение фильтрацтя производиться не будет
    @with_task                      bit                 = 0,    -- если равно 1, выводить заявки только если есть задачи по ним
    @exclude_system_tasks           bit                 = 0,    -- если равно 1, исключать системные задачи
    @without_executor               bit                 = NULL, -- отбор задания ( 1 - БЕЗ исполнителя; 0 - С исполнителем; NULL - любых)
    @elementUid                     uniqueidentifier    = NULL, -- uid элемента диаграммы
    @simple_search                  nvarchar(200)       = NULL, -- строка для простого поиска
    @credit_type                    bigint              = NULL, -- Тип кредита
    @point_of_sale                  xml                 = NULL, -- список Точек продаж. XML вида <items><item id="1" /><item id="1" /><item id="3" /><item id="4" /></items>
    @contractor_legal               xml                 = NULL, -- список Контрагентов (Автосалоны) продаж. XML вида <items><item id="1" /><item id="1" /><item id="3" /><item id="4" /></items>
    -- для постраничного вывода
    @count                          int                 = 100,          -- сколько записей(заявок) нужно вывести 2147483647
    @from_index                     int                 = 0,            -- сколько записей нужно пропустить, а потом выводить данные
    @total_count                    int                 = 0     OUTPUT, -- сколько всего записей в наборе данных
    @total_pages                    int                 = 0     OUTPUT  -- сколько всего страниц в наборе данных
AS
SET NOCOUNT ON
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED
BEGIN


    --WHILE @@TRANCOUNT > 0 COMMIT TRAN

    --INSERT INTO dbo.debug(debug_data)
    --SELECT 
    --    x = 
    --    (
    --        SELECT
    --            @status_list AS status_list,                    
    --            @app_executor_groups AS app_executor_groups,             
    --            @incoming_channel AS incoming_channel,
    --            @region AS region,                         
    --            @branch AS branch,                         
    --            @executor AS executor,                       
    --            @application_status AS application_status,            
    --            @utm_labels AS utm_labels,                     
    --            @application_number AS application_number,             
    --            @current_user as [current_user],                   
    --            @full_name as full_name,                      
    --            @birth_date as birth_date,                     
    --            @passport_series as passport_series,                
    --            @passport_number as passport_number,                
    --            @phone as phone,                          
    --            @creation_date_begin as creation_date_begin,            
    --            @creation_date_end as creation_date_end,              
    --            @approval_date_begin as approval_date_begin,            
    --            @approval_date_end as approval_date_end,              
    --            @date_of_completion_begin as date_of_completion_begin,       
    --            @date_of_completion_end as date_of_completion_end,         
    --            @creation_author as creation_author,                
    --            @manager_issued as manager_issued,                 
    --            @manager_fullfilled as manager_fullfilled,             
    --            @manager_declined as manager_declined,               
    --            @amount_requested_begin as amount_requested_begin,         
    --            @amount_requested_end as amount_requested_end,           
    --            @loan_amount_preDecision_begin as loan_amount_preDecision_begin,  
    --            @loan_amount_preDecision_end as loan_amount_preDecision_end,    
    --            @loan_amount_begin as loan_amount_begin,              
    --            @loan_amount_end as loan_amount_end,                
    --            @role as role,                           
    --            @additional_filtering as additional_filtering,           
    --            @with_task as with_task,                      
    --            @exclude_system_tasks as exclude_system_tasks,           
    --            @without_executor as without_executor,               
    --            @elementUid as elementUid,                     
    --            @simple_search as simple_search,                  
    --            @credit_type as credit_type,                    
    --            @point_of_sale as point_of_sale,                  
    --            @contractor_legal AS contractor_legal,
    --            @count AS [count],                          
    --            @from_index AS from_index                  
    --        FOR xml PATH('input'), type
    --    )

--#region Временные таблицы и переменные
    IF OBJECT_ID('tempdb..#Locko_statuses') IS NOT NULL
    BEGIN
        DROP TABLE #Locko_statuses
    END

    IF OBJECT_ID('tempdb..#Locko_id_list') IS NOT NULL
    BEGIN
        DROP TABLE #Locko_id_list
    END

    IF OBJECT_ID('tempdb..#L_Application') IS NOT NULL
    BEGIN
        DROP TABLE #L_Application
    END

    IF OBJECT_ID('tempdb..#TaskBase_Application') IS NOT NULL
    BEGIN
        DROP TABLE #TaskBase_Application
    END

    IF OBJECT_ID('tempdb..#simple_search_Application') IS NOT NULL
    BEGIN
        DROP TABLE #simple_search_Application
    END

    IF OBJECT_ID('tempdb..#utm_label') IS NOT NULL
    BEGIN
        DROP TABLE #utm_label
    END

    IF OBJECT_ID('tempdb..#utm_labeled_Application') IS NOT NULL
    BEGIN
        DROP TABLE #utm_labeled_Application
    END

    CREATE TABLE #utm_labeled_Application(Id bigint NOT NULL PRIMARY KEY)

    CREATE TABLE #utm_label(utm_label varchar(100) NOT NULL PRIMARY KEY)

    CREATE TABLE #simple_search_Application(Id bigint NOT NULL PRIMARY KEY)

    CREATE TABLE #TaskBase_Application([Application] bigint NOT NULL PRIMARY KEY)

    CREATE TABLE #Locko_statuses(id uniqueidentifier NOT NULL /*PRIMARY KEY*/)

    CREATE TABLE #Locko_id_list
    (
        id      bigint NOT NULL,
        [type]  smallint NOT NULL,

        PRIMARY KEY ([type], id)
    )

    CREATE TABLE #L_Application
    (
        --R_N                         int NOT NULL IDENTITY  PRIMARY KEY,
        Id                          bigint PRIMARY KEY,
        [Rank]                      bigint,
        --Branch                      bigint,
        --CreationAuthor              bigint,
        --ApplicationNumber           nvarchar(100),
        --ApplicationStatus           bigint,
        CreationDate                datetime,
        --OddLot                      bit,
        --Region                      bigint,
        --ApprovalDate                datetime,
        --Validity                    datetime,
        --LoanAmountPreDecision       money,
        --AgreedDecision              bigint,
        --SelectedDecisionOnApp       bigint,
        --SelectedProductsOption      bigint,
        --AdditionalProperties        bigint,
        --IncomingChannel             bigint,
        --AmountRequested             money,
        TaskBase_Id                 bigint,
        --Product                     bigint,
        total_count                 int                 
    )

    DECLARE
        @transaction_role                   bit = 0,  -- учитывать поля связанные с Locko_TransactionParticipant
        @current_user_region                bigint = NULL,  -- регион к которому относиться текущий пользователь
        @current_user_branch                bigint = NULL,  -- отделение к которому относиться текущий пользователь
        @current_user_underwriter           bit = 0,        -- 1 - текущий пользователь является андеррайтером
        @dont_show_ac                       bit = 0,        --Не отображать заявки по АК
        @dont_show_cc_with_collateral       bit = 0,        --Не отображать залоговые заявки по ПК
        @dont_show_cc_without_collateral    bit = 0,        --Не отображать беззалоговые заявки по ПК
        @show_ac_msk_spb_only               bit = 0,        --Отображать только заявки МСК и СПб
        @show_ac_region_only                bit = 0         --Отображать только заявки регионов

    DECLARE @Locko_TimeRank TABLE
    (
        RangeTimeFrom   int NOT NULL,
        RangeTimeTill   int NOT NULL,
        TimeRank        bigint NOT NULL

        PRIMARY KEY (RangeTimeFrom, RangeTimeTill)
    )

    DECLARE @system_users TABLE([user_id] bigint PRIMARY KEY)

    INSERT INTO @Locko_TimeRank
    (
        RangeTimeFrom,
        RangeTimeTill,
        TimeRank
    )
    --VALUES
    --    (0,       15,         100),
    --    (15,  180,        200),
    --    (180, 1440,       500),
    --    (1440,    4320,       1000),
    --    (4320,    999999999,  10000)
    VALUES -- between не должен попадать в два промежутка!
        (0,     15,         100),
        (16,    180,        200),
        (181,   1440,       500),
        (1441,  4320,       1000),
        (4321,  999999999,  10000)

    INSERT INTO @system_users
    (
        [user_id]
    )
    SELECT Id
    FROM [User]
    WHERE [Uid] IN( 'C218A7EB-1E45-4056-BF84-C6818A1DABD6', 
                    'F0E949BF-4DA4-4C02-B04C-CA61964B4FE8' )

    IF OBJECT_ID('tempdb..#msk_spb') IS NOT NULL
    BEGIN
        DROP TABLE #msk_spb
    END

    CREATE TABLE #msk_spb (Id int NOT NULL PRIMARY KEY)
--#endregion Временные таблицы и переменные

--#region проверки и установка значений по умолчанию
    SELECT
        @count                          = IIF(ISNULL(@count, 100)<=0, 100, ISNULL(@count, 100)),
        @from_index                     = IIF(ISNULL(@from_index, 0)<0, 0, ISNULL(@from_index, 0)),
        @full_name                      = NULLIF(RTRIM(LTRIM(@full_name)), ''),
        @birth_date                     = CAST(@birth_date AS date),
        @application_number             = NULLIF(REPLACE(RTRIM(LTRIM(@application_number)), ' ', ''), ''), 
        @passport_series                = NULLIF(REPLACE(RTRIM(LTRIM(@passport_series)), ' ', ''), ''),                 -- серия паспорта
        @passport_number                = NULLIF(REPLACE(RTRIM(LTRIM(@passport_number)), ' ', ''), ''),                 -- номер паспорта
        @phone                          = NULLIF(LTRIM(RTRIM(@phone)), ''),                                             -- номер телефона основного заёмщика
        @creation_date_begin            = CAST(@creation_date_begin AS date),                                           -- Дата создания 
        @creation_date_end              = CAST(@creation_date_end AS date),                                             -- Дата создания 
        @approval_date_begin            = CAST(@approval_date_begin AS date),                                           -- Дата одобрения
        @approval_date_end              = CAST(@approval_date_end AS date),                                             -- Дата одобрения
        @date_of_completion_begin       = CAST(@date_of_completion_begin AS date),                                      -- Дата заполнения
        @date_of_completion_end         = CAST(@date_of_completion_end AS date),                                        -- Дата заполнения
        @creation_author                = IIF(@creation_author<=0, NULL, @creation_author),                             -- Автор создания
        @manager_issued                 = IIF(@manager_issued<=0, NULL, @manager_issued),                               -- Сотрудник, который выдал кредит
        @manager_fullfilled             = IIF(@manager_fullfilled<=0, NULL, @manager_fullfilled),                       -- Сотрудник, который завершил заполнение заявки
        @manager_declined               = IIF(@manager_declined<=0, NULL, @manager_declined),                           -- Сотрудник, который выбрал отказ или брак
        @amount_requested_begin         = IIF(@amount_requested_begin<=0, NULL, @amount_requested_begin),               -- Запрошенная сумма
        @amount_requested_end           = IIF(@amount_requested_end<=0, NULL, @amount_requested_end),
        @loan_amount_preDecision_begin  = IIF(@loan_amount_preDecision_begin<=0, NULL, @loan_amount_preDecision_begin), -- Сумма по предварительному решению
        @loan_amount_preDecision_end    = IIF(@loan_amount_preDecision_end<=0, NULL, @loan_amount_preDecision_end),
        @loan_amount_begin              = IIF(@loan_amount_begin<=0, NULL, @loan_amount_begin),                         -- Сумма из выбранного решения
        @loan_amount_end                = IIF(@loan_amount_end<=0, NULL, @loan_amount_end),
        @role                           = ISNULL(@role,0),
        @additional_filtering           = IIF(ISNULL(@additional_filtering, -1) in(1,2,3,4), @additional_filtering, -1),-- одно из допустимых значений
                                                                                                                        -- По региону - 1
                                                                                                                        -- По отделению - 2
                                                                                                                        -- Дистанционный офис - 3
                                                                                                                        -- Колл-центр - 4
        @with_task                      = ISNULL(@with_task, 0),                                                        -- если равно 1, выводить заявки только если есть задачи по ним
        @exclude_system_tasks           = ISNULL(@exclude_system_tasks, 0),                                             -- если равно 1, исключать системные задачи
        @simple_search                  = NULLIF(LTRIM(RTRIM(@simple_search)), ''),                                     -- строка для простого поиска
        @credit_type                    = IIF(ISNULL(@credit_type, 0)<=0, NULL, @credit_type)                           -- Тип кредита

    SELECT
        @simple_search = IIF(LEN(@simple_search)<3, NULL, @simple_search), -- по слишком короткой строке искать не будем
        @from_index = FLOOR( CAST(@from_index AS float) / CAST(@count AS float) ) * @count     -- подравняем индекс
--#endregion проверки и установка значений по умолчанию

/*перекрываем значения некоторых параметров в зависимости от значения других*/
    If @elementUid IS NOT NULL
    BEGIN
        -- если указан uid элемента диаграммы
        -- то выводить заявки только если есть задачи по ним
        SET @with_task = 1
    END

    -- @exclude_system_tasks находится в зависимости от @without_executor
    SET @exclude_system_tasks = 
        CASE 
            WHEN @without_executor IS NULL THEN     -- NULL - отбор любых задач
                @exclude_system_tasks
            WHEN @without_executor <> 0 THEN       -- 1 - БЕЗ исполнителя, т.е. показывать задачи ТОЛЬКО системных пользователей;
                0
            WHEN @without_executor = 0 THEN        -- 0 - С исполнителем. т.е. показывать задачи ТОЛЬКО НЕ системных пользователей
                1
        END

    SET @with_task = IIF(@without_executor IS NOT NULL, 1, @with_task)

    -- обработаем строку с номером
    IF LEN(ISNULL(@phone, ''))>1
    BEGIN
        -- уберем из строки все символы кроме чисел
        ;WITH locko_Phone AS (
            SELECT
                ch  = SUBSTRING(@phone, 1, 1),
                s   = RIGHT(@phone, LEN(@phone)-1),
                pos = 1

            UNION ALL
            SELECT
                ch  = SUBSTRING(s, 1, 1),
                s   = RIGHT(s, LEN(s)-1),
                pos = pos + 1
            FROM
                locko_Phone
            WHERE 
                s!=''
        ),
        _Phone(s) AS (
            SELECT
                ISNULL(IIF(PATINDEX('[0-9]', ch)>0, ch, ''), '')
            FROM
                locko_Phone
            ORDER BY
                pos
            FOR XML PATH('')
        )
        SELECT
            @phone = NULLIF(RTRIM(LTRIM(s)), '')
        FROM
            _Phone
        OPTION (MAXRECURSION 1000)
    END

    -- по одной цифре искать не будем
    SET @phone = IIF(LEN(@phone)<=1, NULL, @phone)

    IF @phone IS NOT NULL
    BEGIN
        -- найдем заявки по номеру телефона
        /*
        ;WITH Participants AS (
            SELECT 
                p.Participant_id, p.FormatedPhoneString
            FROM
                dbo.v_MobilePhone as p WITH(NOEXPAND)
            WHERE 
                CHARINDEX(@phone, p.FormatedPhoneString)>0

            UNION ALL
            SELECT 
                p.Participant_id, p.FormatedPhoneString
            FROM
                dbo.v_WorkPhone AS p WITH(NOEXPAND)
            WHERE 
                CHARINDEX(@phone, p.FormatedPhoneString)>0

            UNION ALL
            SELECT 
                p.Participant_id, p.FormatedPhoneString
            FROM
                dbo.v_HomePhone AS p WITH(NOEXPAND)
            WHERE 
                CHARINDEX(@phone, p.FormatedPhoneString)>0

            UNION ALL
            SELECT 
                p.Participant_id, p.FormatedPhoneString
            FROM
                v_RegPlacePhone AS p WITH(NOEXPAND)
            WHERE 
                CHARINDEX(@phone, p.FormatedPhoneString)>0
        ),
        l_app AS (
            SELECT
                t.[Application]
            FROM
                Participants as p
                INNER JOIN dbo.v_Locko_TransactionParticipants AS t WITH(NOEXPAND)
                ON t.id = p.Participant_id
            WHERE
                t.TransactionRole = 2 -- основной заёмщик

            UNION
            SELECT
                p.[Application]
            FROM
                dbo.v_MainBorrowerPhones p WITH(NOEXPAND)
            WHERE 
                CHARINDEX(@phone, p.FormatedPhoneString)>0
        )
        INSERT INTO #Locko_id_list(id, [type])
        SELECT a.[Application], 8 -- заявки найденные по номеру телефона
        FROM l_app AS a
        */
        -- найдем заявки по номеру телефона
        INSERT INTO #Locko_id_list(id, [type])
        SELECT 
            t.[Application],
            8
        FROM
            dbo.v_MobilePhone as p WITH(NOEXPAND)
            INNER JOIN dbo.v_Locko_TransactionParticipants AS t WITH(NOEXPAND)
            ON t.id = p.Participant_id
        WHERE 
            CHARINDEX(@phone, p.FormatedPhoneString)>0
            AND t.TransactionRole = 2 -- основной заёмщик
        GROUP BY t.[Application]
    END

    IF @additional_filtering = 1
    BEGIN
        -- получим регионы текущего пользователя
        INSERT INTO #Locko_id_list(id, [type])
        SELECT 
            b.Id, 1000
        FROM
            Locko_Branch AS b
            INNER JOIN UserSecuritySetCache ug
            ON b.CMGroup = ug.GroupId
        WHERE
            ElementType = 1
            and ug.UserId = @current_user -- идентификатор пользователя

        SET @current_user_region = 1

    END
    ELSE IF @additional_filtering = 2
    BEGIN
        /*
        ;WITH Branch AS 
        (
            SELECT
                Branch = Id,
                Parent,
                ElementType,
                CMGroup,
                lvl = 1
            FROM
                Locko_Branch 
            WHERE
                ElementType = 3

            UNION ALL 
            SELECT 
                b.Branch,
                l.Parent,
                l.ElementType,
                l.CMGroup,
                lvl = b.lvl + 1
            FROM 
                Branch AS b
                INNER JOIN Locko_Branch AS l
                ON b.Parent = l.Id
            WHERE
                (b.lvl + 1)<50
        )
        INSERT INTO #Locko_id_list(id, [type]) -- 7 - отделения текущего пользователя
        SELECT b.Id, 7 -- отделения текущего пользователя
        FROM
            Branch AS bb
            INNER JOIN Locko_Branch as b
                ON b.Id = bb.Branch
            INNER JOIN UserSecuritySetCache ug
                ON bb.CMGroup = ug.GroupId
        WHERE
            bb.ElementType=1
            and ug.UserId = @current_user -- идентификтор пользователя
        GROUP BY
            b.Id
        */
        -- не поднимаемся по иерархии, а просто берем с пользователя
        SELECT @current_user_branch = Branch
        FROM [user]
        WHERE Id = @current_user --AND Branch IS NOT NULL
    END

    SELECT
        --данные по основному заёмщику т.е. если хоть что-то из этого есть нужно это учитывать
        @transaction_role       =  IIF(
                                    @full_name          IS NOT NULL
                                    OR @birth_date      IS NOT NULL
                                    OR @passport_series IS NOT NULL
                                    OR @passport_number IS NOT NULL,
                                    1,
                                    0)

    -- если хоть что-то задано
    IF @creation_date_end IS NOT NULL OR @creation_date_begin IS NOT NULL
    BEGIN
        SELECT
            @creation_date_begin    = ISNULL(@creation_date_begin, '1753-01-01'),                                                               -- Дата создания ОТ
            @creation_date_end      = CAST(CONVERT(varchar(10), ISNULL(@creation_date_end, '9999-12-31'), 120) + ' 23:59:59.997' AS datetime)   -- Дата создания ДО
    END

    IF @approval_date_begin IS NOT NULL OR @approval_date_end IS NOT NULL
    BEGIN
        SELECT
            @approval_date_begin    = ISNULL(@approval_date_begin, '1753-01-01'),                                                               -- Дата одобрения ОТ
            @approval_date_end      = CAST(CONVERT(varchar(10), ISNULL(@approval_date_end, '9999-12-31'), 120) + ' 23:59:59.997' AS datetime)   -- Дата одобрения ДО
    END

    IF @date_of_completion_begin IS NOT NULL OR @date_of_completion_end IS NOT NULL
    BEGIN
        SELECT
            @date_of_completion_begin   = ISNULL(@date_of_completion_begin, '1753-01-01'),                                                              -- Дата заполнения ОТ
            @date_of_completion_end     = CAST(CONVERT(varchar(10), ISNULL(@date_of_completion_end, '9999-12-31'), 120) + ' 23:59:59.997' AS datetime)  -- Дата заполнения ДО
    END

