            1
        FROM
            @app_executor_groups.nodes('/items/item') t(f)
        WHERE
            TRY_CAST(t.f.value('(./@id)[1]', 'varchar(100)') AS bigint) IS NOT NULL

        IF NOT EXISTS(SELECT TOP(1) 1 FROM #Locko_id_list WHERE [type]=1)
