        WHERE
            TRY_CAST(t.f.value('(./@id)[1]', 'varchar(100)') AS bigint) IS NOT NULL

        IF NOT EXISTS(SELECT TOP(1) 1 FROM #Locko_id_list WHERE [type]=100)
        BEGIN
            SET @point_of_sale = NULL
        END
    END

    -- список Контрагентов (Автосалоны) продаж. XML вида <items><item id="1" /><item id="1" /><item id="3" /><item id="4" /></items>
    IF @contractor_legal IS NOT NULL
    BEGIN
        INSERT INTO #Locko_id_list(id, [type])
        SELECT DISTINCT
            TRY_CAST(t.f.value('(./@id)[1]', 'varchar(100)') AS bigint),
            101
        FROM
            @contractor_legal.nodes('/items/item') t(f)
        WHERE
            TRY_CAST(t.f.value('(./@id)[1]', 'varchar(100)') AS bigint) IS NOT NULL

        IF NOT EXISTS(SELECT TOP(1) 1 FROM #Locko_id_list WHERE [type]=101)
        BEGIN
            SET @contractor_legal = NULL
        END
        ELSE
        BEGIN
            -- получим все точки продаж контрагента
            INSERT INTO #Locko_id_list(id, [type])
            SELECT
                ps.Child, --  Locko_PointOfSale.Id -- его точки продаж
                100
            FROM
                dbo.ContractorLegal AS cl
                INNER JOIN #Locko_id_list AS l
                ON (cl.HeadOrganozation = l.id or cl.id = l.id)
                AND l.[type]=101
                INNER JOIN M_CL_PointsOfSale AS ps
                ON ps.Parent = cl.id
            WHERE 
                @point_of_sale IS NULL -- если тут пусто значит список точек продаж нам не передали
                -- или он какой-то не очень хороший
                -- поэтому заполняем этот список найденными значениями
                -- иначе используем переданный нам список значений 
            GROUP BY
                ps.Child
        END
    END

    IF EXISTS(SELECT TOP(1) 1 FROM #Locko_id_list WHERE [type]=100) AND @point_of_sale IS NULL
    BEGIN
        -- если тут что-то есть
        -- нужно заполнить значением переменную @point_of_sale
        -- иначе фильтрация не будет работать.
        SET @point_of_sale = CAST('<items><i>1</i></items>' AS xml)
    END

    /*******************************************************/
    -- сформируем список групп Верификаторы и Андерайтеры
    ;WITH Groups_Map AS (
        SELECT
            g.ParentId,
            g.ChildId
        FROM
