    )
    BEGIN
        SET @current_user_underwriter = 1 -- текущий пользователь андеррайтер
    END
    /*******************************************************/

    --#region Наличие ролей "Не отображать заявки"
    SELECT
        @dont_show_ac                       = ISNULL(MAX(CASE WHEN ug.[Uid] = '2E275FF3-C7F4-4AA3-97ED-33C69ED5C91A' THEN 1 END), 0), --Не отображать заявки по АК
        @dont_show_cc_with_collateral       = ISNULL(MAX(CASE WHEN ug.[Uid] = '46B677F9-8451-4F6B-9F96-0AE1DAFA67D9' THEN 1 END), 0), --Не отображать залоговые заявки по ПК
        @dont_show_cc_without_collateral    = ISNULL(MAX(CASE WHEN ug.[Uid] = '3D01C365-280A-416D-AE13-B076F5BB2097' THEN 1 END), 0), --Не отображать беззалоговые заявки по ПК
        @show_ac_msk_spb_only               = ISNULL(MAX(CASE WHEN ug.[Uid] = '46A68EAF-CFDE-4311-93B2-40A68AFC0358' THEN 1 END), 0), --Отображать только заявки МСК и СПб
        @show_ac_region_only                = ISNULL(MAX(CASE WHEN ug.[Uid] = '960A9A3F-581D-47A8-951F-360EE94A57A7' THEN 1 END), 0)  --Отображать только заявки регионов
    FROM
        dbo.UserSecuritySetCache AS us
            INNER JOIN dbo.UserGroup AS ug
            ON ug.Id = us.GroupId
    WHERE
        us.UserId = @current_user
    --#endregion Наличие ролей "Не отображать заявки"

    --#region Список регионов МСК СПБ
    -- Имеет смысл проверять только в случае, если нет запрета на показ АК и установлен только один из признаков региональности
    IF @dont_show_ac = 0
        AND 
        (
            (
                @show_ac_msk_spb_only = 0 AND 
                @show_ac_region_only  = 1
            ) 
            OR
            (
                @show_ac_msk_spb_only = 1 AND 
                @show_ac_region_only  = 0
            )
        )
    BEGIN

        ;WITH cte_branch AS
        (
            SELECT 
                lb.Id,
                lb.Parent,
                lb.[Uid]
            FROM dbo.Locko_Branch lb
            WHERE lb.[Uid] IN ('87A9F1CA-EC04-42C5-85BE-7C854FEADE6F', '25E3A975-493F-405B-879A-08F501DF1340') -- МСК СПБ
            UNION ALL 
            SELECT 
                lb.Id,
                lb.Parent,
                lb.[Uid]
            FROM dbo.Locko_Branch lb
                INNER JOIN cte_branch cb
                ON cb.Id = lb.Parent
        )
        INSERT INTO #msk_spb(Id)
        SELECT Id
        FROM cte_branch

    END
    ELSE -- Смысла проверять нет
    BEGIN 

        SELECT 
           @show_ac_msk_spb_only = 1, 
           @show_ac_region_only  = 1

    END  
    --#endregion 

/***************************************************************/
-- ограничение для КМ
DECLARE @is_KM int

    -- сформируем список групп Верификаторы и Андерайтеры
    ;WITH Groups_Map AS (
        SELECT
            g.ParentId,
            g.ChildId
        FROM
            dbo.UserGroup_Groups_Map as g
            INNER JOIN (
                SELECT *
                FROM UserGroup
                WHERE 
                    id = 102  -- Кредитные менеджеры и колл-центр
            ) as l 
            ON g.ParentId = l.id

        UNION ALL
        SELECT 
            g.ParentId, 
            g.ChildId
        FROM
            Groups_Map AS t
            INNER JOIN [dbo].[UserGroup_Groups_Map] as g
            ON t.ChildId = g.ParentId
    ),
    groups(GroupId) AS (
        SELECT ParentId FROM Groups_Map
        union SELECT ChildId FROM Groups_Map
    )
    select @is_KM = sum(IIF(g.GroupId IS NOT NULL, 1, 0)) 
    from dbo.UserSecuritySetCache AS c
        LEFT JOIN groups AS g 
        ON c.GroupId = g.GroupId
    WHERE
        c.GroupId <> 2 -- Все пользователи
        and UserId = @current_user

    --SET @is_KM = IIF(ISNULL(@is_KM, 0)>0, 183, 1200)

    SET @creation_date_begin = ISNULL(@creation_date_begin, DATEADD(month, IIF(@is_KM > 0, -6, -600), GETDATE())) -- минус полгода или 100 лет
    SET @creation_date_end   = ISNULL(@creation_date_end, '2100-01-01')

/***************************************************************/

/* ****  Ограничение для КМ по CRC-1286 */
    DECLARE 
        @is_KM_1286 int, -- КМ в терминах 1286 отличается
        @is_CC_1286 int  -- Контакт-центр

    IF EXISTS 
        (
            SELECT
                ug.Id
            FROM dbo.UserGroup ug
                INNER JOIN dbo.UserSecuritySetCache AS c
                ON c.GroupId = ug.Id                 
            WHERE c.UserId = @current_user AND 
                (ug.Name LIKE 'КМ %' OR ug.Name = 'Кредитные менеджеры') 

        )
        SET @is_KM_1286 = 1
    ELSE                  
        SET @is_KM_1286 = 0

    IF EXISTS 
        (
            SELECT
                ug.Id
            FROM dbo.UserGroup ug
                INNER JOIN dbo.UserSecuritySetCache AS c
                ON c.GroupId = ug.Id                 
            WHERE c.UserId = @current_user AND 
                ug.Name IN 
                    (
                        'Колл-центр',
                        'Руководитель колл-центра',
                        'Колл-центр - согласование НСТ',
                        'Дистанционный офис'
                    )            
        )
        SET @is_CC_1286 = 1
    ELSE                  
        SET @is_CC_1286 = 0

/***************************************************************/


    IF @with_task = 1
    BEGIN
        INSERT INTO #TaskBase_Application
        (
            [Application]
        )
        SELECT  [Application]
        FROM
            dbo.TaskBase                                        AS tb
            INNER JOIN #Locko_statuses                          AS s
                ON s.id = tb.Status
            LEFT JOIN   dbo.WorkflowBookmark                    AS wfb
                ON tb.WorkflowBookmark = wfb.Id
            LEFT JOIN #Locko_id_list                            AS g -- это пункт 25 
                ON g.id = tb.ApplicationExecutorGroup
                AND g.[type] = 1
            LEFT JOIN #Locko_id_list                            AS l5 -- это пункт 12
                ON l5.id =tb.Executor
                AND l5.[type] = 5
            LEFT JOIN @system_users                             AS su
                ON tb.Executor = su.[user_id]
        WHERE
            tb.CreationDate > @creation_date_begin AND 
            tb.[Application] IS NOT NULL
            AND (
                wfb.ElementUid = @elementUid
                OR @elementUid IS NULL
            )
            AND (
                --Дистанционный офис - 3
                tb.ShowToRemoteOffice != 0 
                OR @additional_filtering != 3 -- или у нас какой-то другой способ фильтрации
            )
            AND (
                -- Колл-центр - 4
                tb.ShowToRemoteOffice = 0 
                OR @additional_filtering != 4 -- или у нас какой-то другой способ фильтрации
                -- CRC-1286 разрешить смотреть такие задачи КЦ независимо от канала поступления
                OR 
                (
                    tb.[Subject] = 'Выбор даты и времени сделки и способа оформления' AND 
                    @is_CC_1286 = 1
                ) 
            )
            AND (
                g.id IS NOT NULL
                OR @app_executor_groups IS NULL
            )
            AND (
                l5.id IS NOT NULL
                OR @executor IS NULL
            )
            AND 
            (
                su.[user_id] IS NULL -- т.е. только те пользователи, которых нет в таблице @system_users
                OR @exclude_system_tasks = 0 -- или когда мы не исключаем системных пользователей
            )
            AND
            (
                su.[user_id] IS NOT NULL -- задачи только системных пользователей для @without_executor<>0
                OR ISNULL(@without_executor, 0) = 0
            )
            /*
            SET @exclude_system_tasks = 
                CASE 
                    WHEN @without_executor IS NULL THEN     -- NULL - отбор любых задач
                        @exclude_system_tasks
                    WHEN @without_executor = 0 THEN        -- 0 - С исполнителем. т.е. показывать задачи ТОЛЬКО НЕ системных пользователей
                        1
                    WHEN @without_executor <> 0 THEN       -- 1 - БЕЗ исполнителя, т.е. показывать задачи ТОЛЬКО системных пользователей;
                        0
                END
            */


        GROUP BY [Application]
    END

    PRINT CONCAT(@is_KM_1286, @is_CC_1286)

    IF @simple_search IS NOT NULL
    BEGIN
        -- выполним простой поиск

        ;WITH simple_search(Id) AS (
            -- по наименованию заявки
            SELECT 
                this_.Id
            FROM    
                dbo.Locko_Application   AS this_
            WHERE
                CHARINDEX(@simple_search, this_.[Name])>0
                AND this_.CreationDate > @creation_date_begin

            -- по ФИО основного заёмщика
            UNION ALL
            SELECT
                locko_tran1_.[Application]
            FROM
                dbo.v_Locko_TransactionParticipants AS locko_tran1_ WITH(NOEXPAND)
            WHERE
                CHARINDEX(@simple_search, locko_tran1_.FullName)>0
                AND locko_tran1_.TransactionRole = 2 -- основной заёмщик

            -- найдем заявки по номеру телефона
            UNION ALL
            SELECT 
                t.[Application]
            FROM
                dbo.v_MobilePhone as p WITH(NOEXPAND)
                INNER JOIN dbo.v_Locko_TransactionParticipants AS t WITH(NOEXPAND)
                ON t.id = p.Participant_id
            WHERE 
                CHARINDEX(@simple_search, p.FormatedPhoneString)>0
                AND t.TransactionRole = 2 -- основной заёмщик
        )
        INSERT INTO #simple_search_Application(Id)
        SELECT
            Id
        FROM
            simple_search
        GROUP BY
            Id
    END

/****************************************************************/
        --Приоритеты при отборе:
        --1. Задача, в которой исполнителем является текущий пользователь      
        --        dbo.TaskBase.Executor = @current_user.
        --2. Задача, в группу исполнителя (app.ExecutorGroup) которой входит текущий пользователь
        --        dbo.TaskBase.ApplicationExecutorGroup
        --    -- группы пользователя
        --    select GroupId
        --    from UserSecuritySetCache ug
        --    where ug.UserId = 8082

        --3. Любая другая задача кроме задачи мониторинга на мошенничество 
        --4. Задача по процессу "Мониторинг на мошенничество" (если пп.1-3 не выполнились)
    CREATE TABLE #temp_Locko_TaskBase
    (
        [Application]   bigint NOT NULL PRIMARY KEY,
        id              bigint NOT NULL,
        [Rank]          int,                            -- t.time_range,
        Executor        bigint,
        task_name_flag  int
    )

    ;WITH cte_hardcoded_user_groups (GroupId) AS -- Таблица 1 CRC-822
    (
        SELECT 
            GroupId = [ChildId]  
        FROM [dbo].[UserGroup_Groups_Map]  
            INNER Join ELMA.dbo.UserGroup AS UG  
            ON UG.Id = ParentId 
        WHERE UG.Uid='2871CA56-7990-4888-B48D-4BE7E1C3C498'
    )
    INSERT INTO #temp_Locko_TaskBase
    (
        id,
        [Application],
        [Rank],
        Executor,
        task_name_flag
    )
    SELECT 
        t.id,
        t.[Application],
        [Rank] = ISNULL(tr.TimeRank, 0), --t.time_range,
        t.Executor,
        task_name_flag
    FROM (
        SELECT
            RN = ROW_NUMBER() OVER 
                (
                    PARTITION BY tb.[Application] -- нумеруем строки в рамках одной заявки
                    ORDER BY
                        CASE 
                            WHEN tb.Executor=@current_user  THEN 0   -- Задача, в которой исполнителем является текущий пользователь 
                            WHEN ug.UserId IS NOT NULL      THEN 1
                            WHEN w.WorkflowBookmark IS NOT NULL THEN 3
                            ELSE 2
                        END
                ),
            tb.id,
            tb.[Application],
            time_range = DATEDIFF(minute, tb.CreationDate, GETDATE()),
            tb.Executor,
            tb.ExecutorPrevious, 
            task_name_flag = 
                CASE WHEN 
                    tb.[Subject] IN 
                        ( -- список для CRC-1286
                            'Заполнение заявки',
                            --'Предварительное одобрение',
                            'Доработка анкеты',
                            'Корректировка файлов',
                            'Изменение анкеты'--,
                            --'Подготовка к сделке'
                        )
                        THEN 1
                    --WHEN tb.[Subject] = 'Выбор даты и времени сделки и способа оформления'
                      --  THEN 2  
                    ELSE 0
                END 
        FROM
            dbo.TaskBase                                        AS tb
            INNER JOIN #Locko_statuses                          AS s
                ON s.id = tb.Status
            LEFT JOIN   dbo.WorkflowBookmark                    AS wfb
                ON tb.WorkflowBookmark = wfb.Id
            LEFT JOIN #Locko_id_list                            AS g -- это пункт 25 
                ON g.id = tb.ApplicationExecutorGroup
                AND g.[type] = 1
            LEFT JOIN #Locko_id_list                            AS l5 -- это пункт 12
                ON l5.id =tb.Executor
                    AND l5.[type] = 5
            LEFT JOIN @system_users                             AS su
                ON tb.Executor = su.[user_id]
            LEFT JOIN dbo.UserSecuritySetCache                  AS ug
                ON ug.UserId = @current_user
                    AND ug.GroupId = tb.ApplicationExecutorGroup
            LEFT JOIN dbo.v_WorkflowBookmark_Token w WITH(NOEXPAND)
                ON w.WorkflowBookmark = tb.WorkflowBookmark 
                    AND w.Token = 1 
            LEFT JOIN dbo.Locko_Application la
                ON la.Id = tb.[Application]    
        WHERE
            tb.CreationDate > @creation_date_begin AND
            tb.[Application] IS NOT NULL
            AND (
                wfb.ElementUid = @elementUid
                OR @elementUid IS NULL
            )
            AND (
                --Дистанционный офис - 3
                tb.ShowToRemoteOffice != 0 
                OR @additional_filtering != 3 -- или у нас какой-то другой способ фильтрации
            )
            AND (
                -- Колл-центр - 4
                tb.ShowToRemoteOffice = 0 
                OR @additional_filtering != 4 -- или у нас какой-то другой способ фильтрации
                OR 
                (
                    tb.[Subject] = 'Выбор даты и времени сделки и способа оформления' AND 
                    @is_CC_1286 = 1                    
                )
            )
            AND (
                g.id IS NOT NULL
                OR @app_executor_groups IS NULL
            )
            AND (
                l5.id IS NOT NULL
                OR @executor IS NULL
            )
            AND 
            (
                su.[user_id] IS NULL -- т.е. только те пользователи, которых нет в таблице @system_users
                OR @exclude_system_tasks = 0 -- или когда мы не исключаем системных пользователей
            )
            AND
            (
                su.[user_id] IS NOT NULL -- задачи только системных пользователей для @without_executor<>0
                OR ISNULL(@without_executor, 0) = 0
            )
            -- CRC-822 Исключить задачи
            AND
            (
                tb.Executor IS NULL OR 
                la.ApplicationStatus IS NULL OR 
                NOT 
                (
                    -- 5.1.2
                    tb.Executor = 2  
                    -- 5.1.1 текущая задача позаявке TaskBase.Application.ApplicationStatus.ID=3
                    AND la.ApplicationStatus = 3 
                    -- 5.1.3 непустое значение TaskBase.ExecutorPrevious
                    AND tb.ExecutorPrevious IS NOT NULL 
                    -- 5.1.4 текущий пользователь и предыдущий исполнитель (TaskBase.ExecutorPrevious) одновременно НЕ входит в одну из групп (Таблица  1)
                    AND NOT EXISTS 
                        (
                            SELECT *
                            FROM dbo.UserSecuritySetCache ussc
                            WHERE ussc.UserId = @current_user
                                AND ussc.GroupId = ANY (SELECT GroupId FROM cte_hardcoded_user_groups) -- (Таблица  1)
                                AND EXISTS 
                                (
                                    SELECT *
                                    FROM dbo.UserSecuritySetCache ge
                                    WHERE ge.UserId = tb.ExecutorPrevious
                                        AND ge.GroupId = ussc.GroupId
                                )
                        )            
                )
            )
            -- конец CRC-822 Исключить задачи
    ) AS t
    OUTER APPLY
    (
        SELECT 
            tr.TimeRank
        FROM
            @Locko_TimeRank as tr
        WHERE
            IIF(t.time_range<0, 0, t.time_range) BETWEEN tr.RangeTimeFrom AND tr.RangeTimeTill
    ) AS tr
    WHERE t.RN=1
    OPTION (RECOMPILE)



/****************************************************************/

    -- тут пункты 4,5,6,7
    ;WITH TransactionParticipants AS (
        SELECT DISTINCT 
            locko_tran1_.[Application]
        FROM
            dbo.v_Locko_TransactionParticipants             AS locko_tran1_ WITH(NOEXPAND)
        WHERE
            locko_tran1_.TransactionRole = 2 -- основной заёмщик
            -- пункт номер 4
            AND (
                CHARINDEX(@full_name, locko_tran1_.FullName)>0
                OR @full_name IS NULL
            )
            -- пункт номер 5  Дата рождения -- тут может в теории быть время
            AND (
                locko_tran1_.BirthDate = @birth_date -- точное совпадение
                OR @birth_date IS NULL
                )
            -- пункт номер 6
            AND (
                locko_tran1_.PassportSeries = @passport_series
                OR @passport_series IS NULL
                )
            -- пункт номер 7
            AND (
                locko_tran1_.PassportNumber = @passport_number
                OR @passport_number IS NULL
                )
    ),
    L_Application AS (
        -- фильтруем Locko_Application
        SELECT
            this_.Id,
            TaskBaseId = tb.Id,
            [Rank] = ISNULL(tb.[Rank], 0) + ISNULL(this_.ApplicationRank ,0),
            this_.CreationDate                                                 -- Дата поступления
        FROM    
            dbo.Locko_Application                                   AS this_
            LEFT JOIN #temp_Locko_TaskBase                          AS tb
                ON tb.[Application] = this_.Id
            LEFT JOIN TransactionParticipants                       AS TrPr
                ON TrPr.[Application] = this_.id
            LEFT JOIN dbo.Locko_DecisionOnApplication               AS locko_decs0_
                ON locko_decs0_.id = this_.SelectedDecisionOnApp
            LEFT JOIN dbo.Locko_Program                             AS locko_prg0_
                ON locko_decs0_.Program = locko_prg0_.Id
            LEFT JOIN dbo.Locko_Product                             AS lp
                ON lp.id = this_.CreditType
            LEFT JOIN dbo.Locko_ProductOption                       AS locko_ProOp0_
                ON locko_ProOp0_.id = this_.SelectedProductsOption
            LEFT JOIN dbo.Locko_Program                             AS lpr -- для определения признака залога
                ON lpr.Id = locko_ProOp0_.Program                
            LEFT JOIN Locko_ConsumerApplicationInf                  AS locko_ConAppI
                ON this_.AdditionalProperties = locko_ConAppI.Id
            LEFT JOIN #Locko_id_list                                AS l2 -- это пункт 8
                ON l2.id = this_.IncomingChannel
                AND l2.[type] = 2
            LEFT JOIN #Locko_id_list                                AS l3 -- это пункт 9
                ON l3.id = this_.Region
                AND l3.[type] = 3
            LEFT JOIN #Locko_id_list                                AS l4 -- это пункт 10
                ON l4.id = this_.Branch
                AND l4.[type] = 4
            LEFT JOIN #Locko_id_list                                AS l6 -- это пункт 12
                ON l6.id =this_.ApplicationStatus
                AND l6.[type] = 6
            LEFT JOIN #Locko_id_list                                AS l8 -- 8 поиск по номеру телефона
                ON l8.id = this_.id
                AND l8.[type] = 8
            LEFT JOIN #simple_search_Application                    AS lss -- простой поиск
                ON lss.Id = this_.Id
            LEFT JOIN #utm_labeled_Application                      AS utm -- поиск по utm метке
                ON utm.Id = this_.id
            LEFT JOIN #Locko_id_list                                AS lregion
                ON lregion.id = this_.Region
                AND lregion.[type] = 1000
            LEFT JOIN #Locko_id_list                                AS lpos
                ON lpos.id = this_.PointOfSale
                AND lpos.[type] = 100
            LEFT JOIN #msk_spb ms
                ON ms.Id = this_.Branch
        WHERE
            (   -- Тип кредита
                @credit_type IS NULL
                OR this_.CreditType = @credit_type
                OR locko_decs0_.CreditType = @credit_type
                OR locko_ProOp0_.Product = @credit_type
            )
            AND ( -- Точки продаж
                lpos.id IS NOT NULL
                OR @point_of_sale IS NULL
            )
            AND (
                utm.Id IS NOT NULL
                OR @utm_labels IS NULL
            )
            AND (
                lss.Id IS NOT NULL
                OR @simple_search IS NULL
            )
            AND (
                tb.[Application] IS NOT NULL  
                OR @with_task = 0  -- если равно 1, выводить заявки только если есть задачи по ним
            )
            AND (
                l8.id IS NOT NULL
                OR @phone IS NULL
            )
            AND(
                this_.Branch = @current_user_branch
                OR @current_user_branch IS NULL
            )
            AND (
                l2.id IS NOT NULL
                OR @incoming_channel IS NULL
            )
            AND (
                l3.id IS NOT NULL
                OR @region IS NULL
            )
            AND (
                l4.id IS NOT NULL
                OR @branch IS NULL
            )
            AND (
                l6.id IS NOT NULL
                OR @application_status IS NULL
            )
            AND this_.CreationDate BETWEEN @creation_date_begin AND @creation_date_end -- точное совпадение
            AND(
                this_.ApprovalDate BETWEEN @approval_date_begin AND @approval_date_end -- точное совпадение
                OR @approval_date_begin IS NULL
            )
            AND (
                this_.DateOfCompletion BETWEEN @date_of_completion_begin AND @date_of_completion_end -- точное совпадение
                OR @date_of_completion_begin IS NULL
            )
            AND (
                this_.CreationAuthor = @creation_author
                OR @creation_author IS NULL
            )
            AND (
                this_.ManagerIssued = @manager_issued
                OR @manager_issued IS NULL
            )
            AND ( 
                this_.ManagerFullfilled = @manager_fullfilled
                OR @manager_fullfilled IS NULL
            )
            AND (
                this_.ManagerDeclined = @manager_declined
                OR @manager_declined IS NULL
            )
            AND (
                this_.LoanAmountPreDecision BETWEEN @loan_amount_preDecision_begin AND @loan_amount_preDecision_end
                OR @loan_amount_preDecision_begin IS NULL
            )
            AND (   
                -- регион текущего пользователя
                lregion.Id IS NOT NULL
                OR @current_user_region IS NULL
            )
            AND (
                @transaction_role = 0 OR -- учтем элементы фильтра по TransactionParticipant когда нужно
                TrPr.[Application] IS NOT NULL 
            )
            AND (
                locko_decs0_.LoanAmount BETWEEN @loan_amount_begin AND @loan_amount_end
                OR @loan_amount_begin IS NULL
            )
            AND (
                COALESCE(locko_decs0_.LoanAmount, this_.LoanAmountPreDecision, locko_ConAppI.AmountRequested)             -- Запрашиваемая сумма
                    BETWEEN @amount_requested_begin AND @amount_requested_end
                OR @amount_requested_begin IS NULL
            )
            AND(
                CHARINDEX(@application_number, this_.ApplicationNumber)>0
                OR @application_number IS NULL
            )
            -- Обработка групп "Не отображать"
            AND NOT (
                @dont_show_ac = 1 AND                    -- группа: не показывать автокредит
                ISNULL(lp.Code, -1) = 3 AND              -- и это автокредит
                ISNULL(tb.Executor, -1) != @current_user -- и пользователь не исполнитель этой задачи
            )        
            AND NOT (
                @dont_show_cc_with_collateral = 1 AND    -- группа: не показывать потреб.кредит с залогом
                ISNULL(lp.Code, -1) = 1 AND              -- и это потреб.кредит
                ISNULL(lpr.IsCollateral, 0) = 1 AND      -- и залог есть                                                     
                ISNULL(tb.Executor, -1) != @current_user -- и пользователь не исполнитель этой задачи
            )        
            AND NOT (
                @dont_show_cc_without_collateral = 1 AND -- группа: не показывать потреб.кредит без залога
                ISNULL(lp.Code, -1) = 1 AND              -- и это потреб.кредит
                ISNULL(lpr.IsCollateral, 0) = 0 AND      -- и залога нет                                                     
                ISNULL(tb.Executor, -1) != @current_user -- и пользователь не исполнитель этой задачи
            )
            AND -- Группы показывать или нет автокредиты мск спб регион
            ( 
                (@show_ac_msk_spb_only = 1 AND @show_ac_region_only  = 1) -- нет смысла проверять
                OR
                ISNULL(tb.Executor, -1) = @current_user  -- пользователь исполнитель этой задачи
                OR
                (
                    @show_ac_msk_spb_only = 1 AND
                    ms.Id IS NOT NULL 
                )  
                OR
                ( 
                    @show_ac_region_only  = 1 AND
                    ms.Id IS NULL  
                )
            )
            AND -- Ограничения для КМ CRC-1286
            ( -- Показать как было если
                @is_KM_1286 = 0 -- пользователь не КМ
                OR
                @is_CC_1286 = 1 -- если пользователь КЦ, то тоже разрешим смотреть, не смотря на то, что он КМ
                OR
                this_.IncomingChannel = 3 -- Канал поступления ручной ввод
                OR
                tb.task_name_flag = 0 -- Задача не в состоянии из списка
                OR
                tb.task_name_flag IS NULL  
            )
    )--,
    --cte_selection AS
    --(
    --    SELECT 
    --        Id
    --    FROM
    --        L_Application
    --    ORDER BY 
    --        [Rank] DESC,
    --        CreationDate DESC
    --    OFFSET @from_index ROWS
    --    FETCH NEXT @count ROWS ONLY
    --)
    INSERT INTO #L_Application
    (
        [Rank],
        Id,
        CreationDate,
        TaskBase_Id,
        total_count
    )
    SELECT
        [Rank],
        Id,
        CreationDate,
        TaskBase_Id = TaskBaseId,
        total_count = total.[count]
    FROM
        L_Application
        CROSS APPLY (SELECT [count] = COUNT(*) FROM L_Application) total
    --WHERE L_Application.Id = ANY(SELECT Id FROM cte_selection) 
    ORDER BY 
        [Rank] DESC,
        CreationDate DESC
    OFFSET @from_index ROWS
    FETCH NEXT @count ROWS ONLY
    OPTION (RECOMPILE)

    -- всего страниц
    SET @total_count = ISNULL((SELECT TOP 1 total_count FROM #L_Application), 0)
    SET @total_pages = CEILING(@total_count*1.0 / @count*1.0)

    /*********************************************/
    ;WITH Locko_TaskBase AS
    (
        SELECT 
            t.id,
            t.[Application],
            t.CreationDate,
            t.WorkflowBookmark,
            t.[Subject],
            t.Executor,
            t.Status,
            t.ApplicationExecutorGroup,
            t.ShowToRemoteOffice
        FROM (
            SELECT
                tb.id,
                tb.[Application],
                tb.CreationDate,
                tb.WorkflowBookmark,
                tb.[Subject],
                tb.Executor,
                tb.Status,
                tb.ApplicationExecutorGroup,
                tb.ShowToRemoteOffice
            FROM
                #L_Application                                      AS lat
                INNER JOIN dbo.TaskBase                             AS tb
                    ON tb.Id = lat.TaskBase_id
                LEFT JOIN   dbo.WorkflowBookmark                    AS wfb
                    ON tb.WorkflowBookmark = wfb.Id
        ) AS t
    ),
    TransactionParticipants AS (
        SELECT
            locko_tran1_.[Application],
            locko_tran1_.Scoring,
            locko_tran1_.AFScoreSegment,
            locko_tran1_.TransactionRole,
            FullName = LEFT(locko_tran1_.FullName, 300),
            ClientCategoryName = LEFT(locko_ctct0_.[Name], 300),
            CollaterallOffer = 
                                TRY_CAST(
                                        IIF(
                                        EXISTS(
                                            -- Для остальных ролей:
                                            -- Наличие в учасниках сделки (Locko_TransactionParticipant) имущества (Locko_Property) с признаком PledgeAsCollaterallOffer
                                            SELECT  1
                                            FROM   dbo.Locko_Property AS locko_lprop0_
                                            WHERE   locko_lprop0_.TransactionParticipant = locko_tran1_.id
                                                    AND locko_lprop0_.PledgeAsCollaterallOffer = 1
                                        ),
                                        1,
                                        0
                                    )
                                AS bit),
            BusinessOwner =   
                                (
                                    SELECT TOP 1
                                        lwc.ContractType    
                                    FROM dbo.M_LTP_WorkPlaces mlwp
                                        INNER JOIN dbo.Locko_Workplace lw
                                        ON lw.Id = mlwp.Child
                                        INNER JOIN dbo.Locko_WorkContract lwc
                                        ON lwc.Id = lw.WorkContractType
                                    WHERE mlwp.Parent = locko_tran1_.id
                                        --AND lw.WorkContractType = 2
                                    ORDER BY lw.MainWorkplaceFlag DESC, lw.Id -- Основное место работы вперед 
                                ) 

        FROM
            #L_Application lat
            INNER JOIN dbo.v_Locko_TransactionParticipants             AS locko_tran1_ WITH(NOEXPAND)
            ON lat.Id = locko_tran1_.[Application]
            LEFT JOIN Locko_ClientCategory                  AS locko_ctct0_ 
                ON locko_tran1_.Category = locko_ctct0_.Id
        WHERE
            locko_tran1_.TransactionRole = 2 -- основной заёмщик
    ),
    main_data AS (
        SELECT
            --NUMBER = this_.R_N,
            tmp_this_.[Rank],
            [Application] = tmp_this_.Id,

            TaskBase_Id = 
                CASE
                    WHEN w.Token
                        IN( 1, -- 'MonitoringFraud'
                            3, -- OddLotApprove
                            4 -- PersonalConditionApprove
                        ) THEN NULL -- возвращать NULL если есть такой токен
                    ELSE -- иначе делаем проверки
                        IIF(
                            dbo.f_CheckTask(tb.ApplicationExecutorGroup, tb.Executor, tb.ShowToRemoteOffice, @current_user, tb.[Subject] ) != 0,
                            tmp_this_.TaskBase_Id,
                            NULL
                        )
                END,

            WorkflowBookmark = tmp_this_.TaskBase_Id, --this_.TaskBase_WorkflowBookmark,

            Assign = 
                CASE 
                    WHEN w.Token 
                        IN( 2,  -- 'VerificationUnderwriting'
                            1,  -- 'MonitoringFraud'
                            5,  -- 'UWChecking'
                            6   -- 'HeadUWAccept'
                        ) THEN 0 -- если есть какой-то из этих токенов выводим 0
                    ELSE 1
                END,
            this_.Branch,
            BranchName = locko_brn0_.Name,
            this_.CreationAuthor,                                               -- Менеджер
            CreationFullName = usr0_.FullName,
            this_.ApplicationNumber,                                            -- Номер
            TrPr.TransactionRole,
            TrPr.FullName,                                                      -- ФИО клиента

            TrPr.ClientCategoryName,                                            -- Категория
            TrPr.BusinessOwner,                                                 -- Собственнник бизнеса
            this_.ApplicationStatus,                                            -- Статус
            AppStatusName = locko_apps0_.Name,

            tmp_this_.CreationDate,                                             --Дата поступления

            Product = COALESCE(locko_decs2_.CreditType, this_.CreditType, locko_ProOp0_.Product), --this_.Product, --ISNULL(locko_decs2_.CreditType, locko_ProOp0_.Product),   --Программа
            ProductName = locko_prd0_.Name, --ISNULL(locko_prd0_.Name, locko_prd1_.Name),

            date_of_insert = tmp_this_.CreationDate,                            -- Дата создания

            [Subject] = tb.[Subject],                                           -- Задача

            Program = ISNULL(locko_decs2_.Program, locko_ProOp0_.Program),      --Тариф
            ProgramName = ISNULL(locko_prg0_.Name, locko_prg1_.Name),           --Тариф

            TrPr.Scoring,                                                      --Скорсегмент
            TrPr.AFScoreSegment,                                               --Специализированный скорсегмент

            CollaterallOffer = TRY_CAST(
                                    IIF(                                        --Наличие залога
                                    @role = 1,
                                    IIF(    EXISTS(
                                                SELECT TOP(1) 1
                                                FROM
                                                    M_LDOA_Collaterals as M
                                                    INNER JOIN Locko_CollateralsDSS as C
                                                    ON C.Id=M.Child
                                                WHERE
                                                    M.Parent = locko_decs2_.id
                                                    AND C.Type = '1'
                                            ),
                                            1,
                                            0
                                    ),
                                    TrPr.CollaterallOffer
                                    )
                                AS bit),

            this_.OddLot,                                                       -- Нестандартная сделка
            this_.Region,                                                       -- Регион
            RegionName = locko_brn1_.Name,
            this_.ApprovalDate,                                                 -- Дата решения
            this_.Validity,                                                     -- Срок действия
            Executor = tb.Executor,                                             -- Исполнитель
            ExecutorName = usr1_.FullName,
            AmountRequested  = COALESCE(locko_decs2_.LoanAmount, this_.LoanAmountPreDecision, locko_ConAppI.AmountRequested),             -- Запрашиваемая сумма
            ApplicationAmountRequested = locko_ConAppI.AmountRequested,
            tb.ApplicationExecutorGroup
        FROM
            #L_Application                                          AS tmp_this_
            INNER JOIN dbo.Locko_Application                        AS this_
                ON this_.Id = tmp_this_.Id
            LEFT JOIN Locko_TaskBase                                AS tb
                ON tb.[Id] = tmp_this_.[TaskBase_Id]
            LEFT JOIN TransactionParticipants                       AS TrPr
                ON TrPr.[Application] = tmp_this_.Id
            LEFT JOIN dbo.Locko_DecisionOnApplication               AS locko_decs2_
                ON locko_decs2_.id = this_.SelectedDecisionOnApp
            LEFT JOIN dbo.Locko_Program                             AS locko_prg0_
                ON locko_decs2_.Program = locko_prg0_.Id
            --LEFT JOIN dbo.Locko_Product                             AS locko_prd0_
            --    ON locko_prd0_.Id = locko_decs2_.CreditType
            LEFT JOIN dbo.Locko_ProductOption                       AS locko_ProOp0_
                ON locko_ProOp0_.id = this_.SelectedProductsOption
            LEFT JOIN dbo.Locko_Product                             AS locko_prd0_
                ON locko_prd0_.Id = COALESCE(locko_decs2_.CreditType, this_.CreditType, locko_ProOp0_.Product)
            --LEFT JOIN dbo.Locko_Product                             AS locko_prd1_
            --    ON locko_ProOp0_.Product = locko_prd1_.Id
            LEFT JOIN dbo.Locko_Program                             AS locko_prg1_
                ON locko_ProOp0_.Program = locko_prg1_.Id
            LEFT JOIN dbo.Locko_Branch                              AS locko_brn0_
                ON this_.Branch = locko_brn0_.Id
            LEFT JOIN dbo.[User]                                    AS usr0_
                ON this_.CreationAuthor=usr0_.Id
            LEFT JOIN dbo.Locko_ApplicationStatus                   AS locko_apps0_
                ON this_.ApplicationStatus= locko_apps0_.Id
            LEFT JOIN dbo.Locko_Branch                              AS locko_brn1_
                ON this_.Region = locko_brn1_.Id
            LEFT JOIN dbo.[User]                                    AS usr1_
                ON tb.Executor = usr1_.Id
            LEFT JOIN Locko_ConsumerApplicationInf                  AS locko_ConAppI
                ON this_.AdditionalProperties = locko_ConAppI.Id
            LEFT JOIN dbo.v_WorkflowBookmark_Token w WITH(NOEXPAND)
                ON w.WorkflowBookmark = tb.WorkflowBookmark     

    )

    SELECT
        --NUMBER = @from_index + NUMBER,
        --total_count = @total_count,   -- сколько всего записей в наборе данных
        --page_number = FLOOR( (CAST(@from_index AS float))/CAST(@count AS float) ),
        --total_pages = @total_pages,   -- сколько всего страниц в наборе данных

        m.[Application],
        m.TaskBase_Id,   -- Если здесь не NULL то будет отображаться кнопка взять в работу
        m.WorkflowBookmark,
        m.Assign,

        m.[Rank],
        m.Branch,
        m.BranchName,                                       -- Наименование отделения
        m.CreationAuthor,                                   -- Менеджер
        m.CreationFullName,                                 -- имя менеджера
        m.ApplicationNumber,                                -- Номер
        m.FullName,                                         -- ФИО клиента
        m.ClientCategoryName,                               -- Категория
        m.ApplicationStatus,                                -- Статус
        m.AppStatusName,                                    -- Нименование статуса
        m.CreationDate,                                     -- Дата поступления
        m.Product,                                          -- Программа
        m.ProductName,
        m.date_of_insert,                                   -- Дата создания

        --m.[Subject],                                      -- Задача
        [Subject] =                                         -- Задача
            CASE
                WHEN  -- Не выводить ФИО исполнителя и название задачи, если (одновременно):
                    (
                        ISNULL(u.Executor_underwriter, 0) = 1 -- Исполнитель задачи входит в группу "Верификаторы и андеррайтеры"
                        OR ISNULL(u2.Executor_underwriter_group, 0) = 1 -- ИЛИ Группа исполнителя входи (ApplicationExecutorGroup) в группу "Верификаторы и андеррайтеры" или равна ей
                    )
                    AND @current_user_underwriter = 0 -- Текущий пользователь не входит в группу "Верификаторы и андеррайтеры"
                THEN
                    NULL
                ELSE
                    m.[Subject]
            END,

        m.Program,                                          -- Тариф
        m.ProgramName,
        m.Scoring,                                          -- Скорсегмент
        m.AFScoreSegment,                                   -- Специализированный скорсегмент
        CollaterallOffer = ISNULL(m.CollaterallOffer,0),    -- Наличие залога
        m.OddLot,                                           -- Нестандартная сделка
        m.Region,                                           -- Регион
        m.RegionName,                                       -- Наименование региона
        m.ApprovalDate,                                     -- Дата решения
        m.Validity,                                         -- Срок действия
        m.Executor,                                         -- Исполнитель

        --m.ExecutorName,                                   -- Наименование исполнителя
        ExecutorName =                                      -- Наименование исполнителя
            CASE
                WHEN  -- Не выводить ФИО исполнителя и название задачи, если (одновременно):
                    (
                        ISNULL(u.Executor_underwriter, 0) = 1 -- Исполнитель задачи входит в группу "Верификаторы и андеррайтеры"
                        OR ISNULL(u2.Executor_underwriter_group, 0) = 1 -- ИЛИ Группа исполнителя входи (ApplicationExecutorGroup) в группу "Верификаторы и андеррайтеры" или равна ей
                    )
                    AND @current_user_underwriter = 0 -- Текущий пользователь не входит в группу "Верификаторы и андеррайтеры"
                THEN
                    NULL
                ELSE
                    m.ExecutorName
            END,
        m.AmountRequested,                                  -- Запрашиваемая сумма
        m.BusinessOwner,                                    -- Собственник бизнеса
        m.ApplicationAmountRequested 
    FROM
        main_data m
        OUTER APPLY (
            SELECT TOP(1) Executor_underwriter = 1
            FROM
                dbo.UserSecuritySetCache AS ug
                INNER JOIN #Locko_id_list as i
                ON i.id=ug.GroupId
                AND i.[type] = 99
            WHERE
                ug.UserId = m.Executor
        ) AS u
        OUTER APPLY (
            SELECT TOP(1) Executor_underwriter_group = 1
            FROM    #Locko_id_list as i
            WHERE   i.[type] = 99
                    AND i.id = m.ApplicationExecutorGroup
        ) AS u2
    ORDER BY
        m.[Rank] DESC,
        m.CreationDate DESC

    RETURN 0;

END
